import{_ as s,o as t,c as n,a5 as o}from"./chunks/framework.CslsFoWx.js";const p=JSON.parse('{"title":"18 — Assistant IA (serveur MCP)","description":"","frontmatter":{},"headers":[],"relativePath":"specs/18-mcp.md","filePath":"generated/specs/18-mcp.md","lastUpdated":null}'),r={name:"specs/18-mcp.md"};function a(i,e,c,u,d,l){return t(),n("div",null,[...e[0]||(e[0]=[o('<div><h1 id="_18-—-assistant-ia-serveur-mcp" tabindex="-1">18 — Assistant IA (serveur MCP) <a class="header-anchor" href="#_18-—-assistant-ia-serveur-mcp" aria-label="Permalink to &quot;18 — Assistant IA (serveur MCP)&quot;">​</a></h1><blockquote><p>Phase : 3 bis · Modules concernés : cœur (aucun module magasin ; droit de formule <code>MCP_ACCESS</code>) · Applications concernées : serveur, nouveau service <code>mcp/</code>, back-office web. Aucune app caisse n&#39;est touchée.</p></blockquote><blockquote><p>Cette spec fixe les <strong>règles</strong> des lots livrés (M0, M1, M3, M2). Le besoin, l&#39;expérience visée, le catalogue d&#39;outils, le plan des lots suivants (U2 → U6, M4) et les sources sont dans <a href="/VendoraSystem-docs/architecture/mcp-vendora">MCP-VENDORA.md</a> ; le mode d&#39;emploi commerçant dans <a href="/VendoraSystem-docs/architecture/mcp-guide">MCP-GUIDE-UTILISATEUR.md</a> ; les routes, champs et codes dans <a href="/VendoraSystem-docs/architecture/api-publique">API-PUBLIQUE.md</a> ; l&#39;exploitation du service dans <a href="./../../mcp/README"><code>mcp/README.md</code></a>. Décisions d&#39;Ahmed du 11/11/2026 : Kotlin, OAuth avant la page du back-office, pas de données clients en v1, droit <code>MCP_ACCESS</code> par formule.</p></blockquote><h2 id="_1-objectif-perimetre" tabindex="-1">1. Objectif &amp; périmètre <a class="header-anchor" href="#_1-objectif-perimetre" aria-label="Permalink to &quot;1. Objectif &amp; périmètre&quot;">​</a></h2><p>Un commerçant pose ses questions de gestion (« combien ai-je vendu hier ? », « que dois-je commander ? ») à l&#39;assistant IA qu&#39;il utilise déjà — Claude, ChatGPT, tout client du protocole MCP — et l&#39;assistant lit les réponses dans Vendora, en <strong>lecture seule</strong>, sur les magasins et les familles de données que le commerçant a choisis.</p><h3 id="ce-que-ca-couvre" tabindex="-1">Ce que ça couvre <a class="header-anchor" href="#ce-que-ca-couvre" aria-label="Permalink to &quot;Ce que ça couvre&quot;">​</a></h3><ul><li>Les prérequis d&#39;accès du serveur (M0) : portées fines, restriction par magasin, clé « Assistant IA », journal des assistants, droit de formule, arrêts d&#39;urgence.</li><li>Le service <code>mcp/</code> (M1) : serveur MCP distant, sans état, client de l&#39;API publique.</li><li>La connexion « en un clic » (M3) : Vendora serveur d&#39;autorisation OAuth 2.1, écran de consentement au back-office, jetons, « Assistants connectés ».</li></ul><h3 id="ce-que-ca-ne-couvre-pas" tabindex="-1">Ce que ça ne couvre PAS <a class="header-anchor" href="#ce-que-ca-ne-couvre-pas" aria-label="Permalink to &quot;Ce que ça ne couvre PAS&quot;">​</a></h3><ul><li>Toute <strong>écriture</strong> par un assistant (lot M4, après le lot GaaS A2).</li><li>Les <strong>données personnelles des clients</strong> du commerce (absentes de la v1 : ni portée proposée au consentement, ni outil).</li><li>La page « Assistant IA » du back-office et le tutoriel (M2), les cartes visuelles (U2), l&#39;annuaire des connecteurs (U6).</li><li>Les agents internes de Vendora (GaaS), qui ont leur propre plan.</li></ul><h2 id="_2-user-stories" tabindex="-1">2. User stories <a class="header-anchor" href="#_2-user-stories" aria-label="Permalink to &quot;2. User stories&quot;">​</a></h2><ul><li>En tant que <strong>propriétaire</strong>, je veux connecter mon assistant à Vendora depuis mon téléphone sans copier de clé, afin d&#39;avoir mes chiffres en posant une question.</li><li>En tant que <strong>propriétaire</strong>, je veux choisir les magasins et les familles de données que l&#39;assistant peut lire, afin de ne partager que ce que je décide.</li><li>En tant que <strong>propriétaire</strong>, je veux voir les assistants connectés et retirer un accès d&#39;un geste, afin de garder la main si un téléphone est perdu.</li><li>En tant qu&#39;<strong>administrateur</strong>, je veux que l&#39;accès d&#39;un collègue désactivé tombe tout seul, afin de ne rien avoir à nettoyer.</li><li>En tant qu&#39;<strong>intégrateur</strong>, je veux une clé « Assistant IA » à mettre dans un en-tête, afin de brancher un script ou Claude Code sans navigateur.</li><li>En tant qu&#39;<strong>équipe Vendora</strong>, je veux couper l&#39;accès des assistants pour tous les commerces en cas d&#39;incident, sans toucher aux ventes ni aux autres intégrations.</li></ul><h2 id="_3-regles-metier" tabindex="-1">3. Règles métier <a class="header-anchor" href="#_3-regles-metier" aria-label="Permalink to &quot;3. Règles métier&quot;">​</a></h2><h3 id="acces-des-assistants-m0" tabindex="-1">Accès des assistants (M0) <a class="header-anchor" href="#acces-des-assistants-m0" aria-label="Permalink to &quot;Accès des assistants (M0)&quot;">​</a></h3><ul><li><strong>RG-MCP-01</strong> — Un assistant est en <strong>lecture seule</strong>, toujours : toute écriture est refusée (403 <code>API_KEY_READ_ONLY</code>), quel que soit le moyen d&#39;authentification.</li><li><strong>RG-MCP-02</strong> — L&#39;accès se règle par <strong>portées fines de lecture</strong> (<code>&lt;famille&gt;:read</code>). Le classement route → portée est <strong>fermé par défaut</strong> : une route non classée n&#39;est ouverte à aucune portée fine, et un test échoue si une route publique de lecture n&#39;est pas classée.</li><li><strong>RG-MCP-03</strong> — Un accès peut être <strong>restreint à des magasins</strong>. Double barrière : contrôle de la route et politique PostgreSQL <code>store_scope</code>. Autre magasin : 404 <code>STORE_NOT_ALLOWED</code> ; lecture du commerce entier : 403 <code>API_KEY_STORE_RESTRICTED</code>.</li><li><strong>RG-MCP-04</strong> — La clé « Assistant IA » (<code>kind = AGENT</code>) est préréglée sur <code>stores</code>, <code>catalog</code>, <code>sales</code>, <code>reports</code>, <code>inventory</code>, <code>purchases</code>, <code>devices</code> — <strong>jamais <code>customers:read</code> d&#39;office</strong> —, limitée à 120 requêtes par minute, et expire toujours (90 jours par défaut, 365 au plus).</li><li><strong>RG-MCP-05</strong> — Le droit de formule <strong><code>MCP_ACCESS</code></strong> conditionne tout accès d&#39;assistant : sans lui, 402 <code>AGENT_ACCESS_NOT_IN_PLAN</code>, à la création comme à chaque requête.</li><li><strong>RG-MCP-06</strong> — <strong>Arrêt d&#39;urgence</strong> par commerce (propriétaire, back-office) et global (console Vendora, motif obligatoire) : effet dès la requête suivante, sans cache (401 <code>AGENT_ACCESS_DISABLED</code> / <code>AGENT_ACCESS_SUSPENDED</code>). Rien n&#39;est supprimé ; les clés « Logiciel tiers », la vente, la synchronisation et les Z ne sont jamais touchés.</li><li><strong>RG-MCP-07</strong> — Chaque lecture <strong>autorisée</strong> d&#39;un assistant est inscrite au <strong>journal des assistants</strong> (<code>agent_activity</code>, acteur <code>AGENT</code>), regroupée par accès, jour, lecture, magasin et période, avec un compteur. Jamais de secret, jamais le contenu lu. Le journal d&#39;audit reste celui des décisions humaines.</li><li><strong>RG-MCP-08</strong> — Aucun secret (clé, jeton, code) n&#39;est stocké en clair, écrit dans un journal, ni accepté dans une adresse. Les secrets sont stockés <strong>hachés</strong> (SHA-256) et montrés une seule fois.</li><li><strong>RG-MCP-09</strong> — Un refus porte un <code>code</code> stable et un message en français <strong>relayable tel quel</strong> : il dit ce qui manque et où le régler.</li></ul><h3 id="serveur-mcp-m1" tabindex="-1">Serveur MCP (M1) <a class="header-anchor" href="#serveur-mcp-m1" aria-label="Permalink to &quot;Serveur MCP (M1)&quot;">​</a></h3><ul><li><strong>RG-MCP-10</strong> — Le service <code>mcp/</code> est un <strong>client de l&#39;API publique</strong> : pas de base de données, pas de secret, pas d&#39;accès privilégié, jamais le rôle <code>pos_platform</code>. Son client HTTP ne sait faire que des <code>GET</code>.</li><li><strong>RG-MCP-11</strong> — Il est <strong>sans état</strong> : chaque requête se suffit (révision 2026-07-28 du protocole, compatibilité 2025-11-25 et antérieures sans session).</li><li><strong>RG-MCP-12</strong> — L&#39;accès de l&#39;appelant (clé ou jeton) est <strong>relayé à chaque requête</strong> à l&#39;API Vendora, qui décide ; il n&#39;est ni gardé ni journalisé. Le journal du service ne contient ni accès, ni argument, ni texte du commerçant.</li><li><strong>RG-MCP-13</strong> — La liste d&#39;outils dépend des portées de l&#39;accès (<code>GET /api/v1/api-keys/me</code>) : un outil dont la portée manque n&#39;est pas proposé, et <code>list_stores</code> dit ce que l&#39;accès n&#39;inclut pas.</li><li><strong>RG-MCP-14</strong> — Chaque réponse d&#39;outil indique la <strong>période réellement utilisée</strong> (dans le fuseau du magasin) et la <strong>fraîcheur</strong> des données ; des données anciennes sont signalées, jamais présentées comme à jour.</li><li><strong>RG-MCP-15</strong> — Un nom ambigu (magasin, produit) ne se devine pas : l&#39;outil renvoie les candidats. Aucun chiffre n&#39;est inventé.</li><li><strong>RG-MCP-16</strong> — Les textes libres venus des données (noms de produits, notes) sont des <strong>données, jamais des consignes</strong> : chaque réponse les balise comme telles.</li><li><strong>RG-MCP-17</strong> — Garde-fous du transport : <code>Origin</code> étranger refusé (403), corps limité à 1 Mo, lots JSON-RPC refusés, <code>GET</code> / <code>DELETE</code> sur <code>/mcp</code> → 405.</li><li><strong>RG-MCP-18</strong> — Les refus de l&#39;API (401, 402, 403, 404, 429) sont rendus à l&#39;assistant avec leur message, sans réessai caché.</li><li><em>RG-MCP-19 à 29 : réservées (cartes visuelles, langue du commerce, écriture encadrée).</em></li></ul><h3 id="connexion-oauth-2-1-m3" tabindex="-1">Connexion OAuth 2.1 (M3) <a class="header-anchor" href="#connexion-oauth-2-1-m3" aria-label="Permalink to &quot;Connexion OAuth 2.1 (M3)&quot;">​</a></h3><ul><li><strong>RG-MCP-30</strong> — Le <strong>serveur Vendora est le serveur d&#39;autorisation</strong> (comptes du back-office), sans service séparé. Émetteur = adresse publique de l&#39;API. Les points que les normes fixent sont hors <code>/api/v1</code> (<code>/.well-known/oauth-authorization-server</code>, <code>/oauth/token</code>, <code>/oauth/revoke</code>, <code>/oauth/register</code>) ; tout le reste (point d&#39;autorisation, consentement, connexions) est sous <code>/api/v1/oauth</code> — une seule API. Le <strong>point d&#39;autorisation</strong> est annoncé sur l&#39;origine du <strong>back-office</strong> (<code>&lt;back-office&gt;/api/v1/oauth/authorize</code>, relayé vers l&#39;API) : c&#39;est ce qui permet de lier la demande au navigateur (RG-MCP-46). Les clients sont <strong>publics</strong> : aucun secret de client n&#39;existe.</li><li><strong>RG-MCP-31</strong> — Le client s&#39;identifie par un <strong>document client</strong> (CIMD : son <code>client_id</code> est une adresse <code>https</code> que le serveur lit) ou, en repli, par <strong>enregistrement dynamique</strong> (DCR). La lecture du document est protégée contre les requêtes vers l&#39;intérieur (SSRF) : <code>https</code> et port 443 seulement, adresse <strong>publique</strong> vérifiée après résolution DNS (<strong>toutes</strong> les adresses rendues doivent être publiques) et connexion faite à l&#39;adresse vérifiée, aucune redirection suivie, <strong>5 secondes pour toute l&#39;opération</strong> (résolution DNS, connexion, poignée de main TLS et lecture comprises : à l&#39;échéance la connexion est fermée), 64 Ko au plus, <strong>8 lectures en parallèle</strong> pour tout le serveur (refus immédiat au-delà, sans file d&#39;attente) ; le document doit se désigner lui-même ; cache de 5 minutes à 24 heures, écrit seulement <strong>une fois la demande entièrement validée</strong>.</li><li><strong>RG-MCP-32</strong> — Une adresse de redirection n&#39;est acceptée que si elle est <strong>exactement</strong> l&#39;une de celles que le client a déclarées ; seule tolérance : le port d&#39;une adresse en boucle locale (<code>localhost</code>, <code>127.0.0.1</code>). Client ou redirection non reconnus : écran d&#39;erreur de Vendora, <strong>jamais de redirection</strong> vers l&#39;adresse présentée. Pour un client <strong>non vérifié</strong> (RG-MCP-36), <strong>aucune erreur</strong> ne repart vers sa redirection, même validée : toute demande incorrecte (type de réponse, PKCE, ressource, portée) finit sur l&#39;écran d&#39;erreur de Vendora (pas de redirection ouverte, RFC 9700 § 4.11.2). Seul un client vérifié reçoit l&#39;erreur à sa redirection. Un paramètre présent deux fois est refusé.</li><li><strong>RG-MCP-33</strong> — Flux : code d&#39;autorisation avec <strong>PKCE S256 obligatoire</strong> (<code>plain</code> et méthode absente refusés), paramètre <code>resource</code> égal à l&#39;adresse d&#39;un serveur MCP connu, <code>state</code> renvoyé à l&#39;identique, <code>iss</code> dans la réponse. Le code vit <strong>60 secondes</strong>, sert <strong>une fois</strong>, et n&#39;est valable que pour le client, la redirection et la ressource de la demande.</li><li><strong>RG-MCP-34</strong> — Le consentement se donne <strong>dans le back-office</strong> (<code>/connecter-assistant?demande=…</code>), après la connexion habituelle. L&#39;adresse ne porte qu&#39;un <strong>identifiant opaque</strong> de la demande (stocké haché, 10 minutes) : jamais un code ni un jeton.</li><li><strong>RG-MCP-35</strong> — Peuvent autoriser : les rôles qui peuvent créer une clé « Assistant IA » (<strong>propriétaire, administrateur</strong>). Les magasins proposés sont ceux que l&#39;utilisateur administre ; tout autre choix est refusé. Une session de <strong>mise en service déléguée</strong> à l&#39;équipe Vendora (spec 17 RG-PLAT-34) ne peut ni voir une demande, ni autoriser, ni lister, ni retirer une connexion : <code>/api/v1/oauth/**</code> y est toujours interdit, comme les clés d&#39;API.</li><li><strong>RG-MCP-36</strong> — L&#39;écran dit <strong>qui demande</strong> (nom et domaine tirés du document client), <strong>où l&#39;on sera renvoyé</strong>, que l&#39;accès est en <strong>lecture seule</strong>, et que <strong>les données choisies sont envoyées à l&#39;assistant choisi</strong>. Un client n&#39;est « Vérifié » que si son <strong>identifiant exact</strong> (l&#39;adresse de son document client) figure dans la liste de confiance du serveur ; tout autre client — et tout client enregistré lui-même — est « Non vérifié ». Le nom affiché est nettoyé et borné à 60 caractères ; un client non vérifié qui se présente sous le nom d&#39;un assistant connu ou de Vendora (Claude, ChatGPT, OpenAI, Anthropic, Vendora… sans tenir compte de la casse, des accents ni des caractères ressemblants) est affiché sous le <strong>domaine de sa redirection</strong> à la place.</li><li><strong>RG-MCP-37</strong> — L&#39;utilisateur choisit les <strong>magasins</strong> (tous, ou une liste) et les <strong>familles</strong> : ventes et rapports, stock, achats, appareils ; anti-fraude seulement si son rôle y a droit, <strong>jamais cochée d&#39;office</strong>. Les données clients ne sont pas proposées. Au moins un magasin et une famille.</li><li><strong>RG-MCP-38</strong> — <strong>Autoriser</strong> ou <strong>Refuser</strong> : la demande ne reçoit qu&#39;une réponse (ensuite 410) ; un refus renvoie <code>access_denied</code> au client (pour un client non vérifié, seulement parce que l&#39;utilisateur connecté l&#39;a décidé lui-même sur l&#39;écran). Arrêt d&#39;urgence actif ou formule sans <code>MCP_ACCESS</code> : l&#39;autorisation est impossible et l&#39;écran dit pourquoi. Écran en français, anglais et arabe (droite à gauche), clair et sombre, téléphone et bureau.</li><li><strong>RG-MCP-39</strong> — Les jetons sont <strong>opaques</strong>, stockés hachés, à préfixe reconnaissable : accès <code>vd_oat_…</code> (1 heure), renouvellement <code>vd_ort_…</code> (90 jours), code <code>vd_oac_…</code>. Une connexion dure 365 jours au plus.</li><li><strong>RG-MCP-40</strong> — Le jeton de renouvellement est <strong>tournant</strong> : chaque usage en émet un nouveau. Un jeton de renouvellement <strong>rejoué</strong>, ou un code présenté deux fois, <strong>révoque toute la connexion</strong>. L&#39;échange du code est <strong>atomique</strong> : la connexion et ses jetons naissent dans la même transaction que le marquage du code, si bien qu&#39;un second échange, même simultané, trouve la connexion et la révoque. Code et jetons ne voyagent que dans le <strong>corps</strong> des requêtes : tout paramètre dans l&#39;adresse du point de jeton ou de révocation est refusé.</li><li><strong>RG-MCP-41</strong> — Un jeton d&#39;accès suit <strong>le chemin de code de la clé « Assistant IA »</strong> : RG-MCP-01 à 09 s&#39;appliquent telles quelles (lecture seule, portées, magasins, journal, arrêts d&#39;urgence, <code>MCP_ACCESS</code>, 120 requêtes par minute). <code>GET /api/v1/api-keys/me</code> répond avec <code>kind: &quot;OAUTH&quot;</code>.</li><li><strong>RG-MCP-42</strong> — L&#39;accès est <strong>recalculé à chaque requête</strong> : utilisateur actif, toujours propriétaire ou administrateur, magasins accordés ∩ magasins qu&#39;il administre encore. Sinon 401 dès la requête suivante, et le renouvellement est refusé (<code>invalid_grant</code>) tant qu&#39;il n&#39;administre plus aucun des magasins accordés.</li><li><strong>RG-MCP-43</strong> — <strong>Retirer l&#39;accès</strong> (back-office, « Assistants connectés » : assistant, par qui, magasins, familles, connecté le, dernière utilisation) ou révocation par le client (RFC 7009) : jetons d&#39;accès et de renouvellement refusés dès la requête suivante. Sont inscrits au journal d&#39;audit (<code>OAUTH_CONNECTION</code>) : l&#39;autorisation (<code>AUTHORIZED</code>), le <strong>refus</strong> du consentement (<code>DENIED</code>) et <strong>tout</strong> retrait (<code>REVOKED</code>, avec son motif : <code>USER</code> au back-office, <code>CLIENT</code> par l&#39;assistant, <code>REPLAY</code> après un rejeu).</li><li><strong>RG-MCP-44</strong> — Le serveur MCP annonce la connexion : sans accès, <strong>401 sur toute méthode</strong> avec <code>WWW-Authenticate: Bearer resource_metadata=&quot;…&quot;</code> ; document de ressource protégée (RFC 9728) à la racine et sous le chemin de la ressource, dont <code>resource</code> est l&#39;adresse publique <strong>exacte</strong> du serveur MCP. Jeton expiré ou retiré : 401 <code>invalid_token</code> (le client renouvelle). Arrêt d&#39;urgence : 403, pour ne pas relancer une connexion en boucle.</li><li><strong>RG-MCP-45</strong> — Les points OAuth répondent en moins de 10 secondes (aucun appel long ; lecture du document client bornée) et sont limités <strong>par adresse appelante et globalement</strong>, par minute : autorisation 120 / 600, jeton et révocation 300 / 3 000, enregistrement 30 / 60. Leurs réponses ne sont jamais mises en cache. Métadonnées, jeton, révocation et enregistrement acceptent les appels d&#39;une autre origine (CORS, sans identifiants) ; le point d&#39;autorisation et le consentement, non.</li><li><strong>RG-MCP-46</strong> — <strong>Liaison au navigateur</strong> : le point d&#39;autorisation pose un cookie (<code>HttpOnly</code>, <code>SameSite=Lax</code>, <code>Secure</code> en https, 10 minutes, limité à <code>/api/v1/oauth</code>) dont seule l&#39;empreinte est gardée avec la demande. Lire la demande, l&#39;autoriser ou la refuser exige ce cookie : un lien de consentement ouvert dans un <strong>autre navigateur</strong> est refusé (403 <code>OAUTH_REQUEST_OTHER_BROWSER</code>) et l&#39;écran invite à relancer la connexion depuis l&#39;assistant.</li><li><strong>RG-MCP-47</strong> — <strong>Stockage borné</strong> : ce que des appelants anonymes font enregistrer est plafonné — 2 000 demandes en attente, 3 000 clients enregistrés, 2 000 documents en cache ; enregistrement de 4 Ko, 5 redirections (10 dans un document client) de 500 caractères, <code>state</code> de 500 caractères. Au-delà : refus, rien n&#39;est écrit. Ménage continu : demandes sans accord 10 minutes après leur fin, clients enregistrés jamais utilisés après une heure (un jour s&#39;ils ont servi sans jamais aboutir à une connexion), documents en cache un jour après leur échéance.</li><li><strong>RG-MCP-48</strong> — <strong>Interrupteur</strong> <code>pos.oauth.enabled</code> (<code>POS_OAUTH_ENABLED</code>), <strong>faux par défaut</strong> : éteint, tous les points OAuth (<code>/oauth/**</code>, <code>/.well-known/oauth-authorization-server</code>, <code>/api/v1/oauth/**</code>) répondent 404 et seules les clés servent. Allumé, le serveur <strong>refuse de démarrer</strong> hors développement et test si l&#39;émetteur ou les ressources ne sont pas posés explicitement, en https.</li><li><strong>RG-MCP-49</strong> — La page <strong>Réglages › Assistant IA</strong> (<code>/assistant-ia</code>) est réservée au <strong>propriétaire et aux administrateurs</strong> : un responsable de magasin ne la voit pas dans le menu et l&#39;adresse directe lui est refusée. Sous délégation Vendora elle s&#39;affiche en lecture seule (aucune connexion, aucun test, aucun arrêt).</li><li><strong>RG-MCP-50</strong> — L&#39;adresse du connecteur affichée vient <strong>du serveur</strong> (première ressource de <code>POS_OAUTH_RESOURCES</code>), jamais d&#39;une constante du back-office ni d&#39;une adresse de repli : sans configuration, aucune adresse n&#39;est montrée. OAuth éteint, les blocs « Connecter Claude / ChatGPT » sont remplacés par un message et seules les clés pour intégrateurs restent. « Connecter ChatGPT » est marqué <strong>Bêta</strong> tant qu&#39;un essai réel n&#39;a pas été fait.</li><li><strong>RG-MCP-51</strong> — <strong>Tester la connexion</strong> répond par <strong>un seul message en clair</strong> : tout va bien · la formule n&#39;inclut pas l&#39;assistant · assistants arrêtés (arrêt d&#39;urgence, ou suspension Vendora qui prime) · le service ne répond pas. Le test est fait par le serveur Vendora (OAuth allumé : le service MCP doit annoncer l&#39;adresse du connecteur dans son document de ressource protégée ; éteint : sa santé suffit), en 8 secondes au plus, sans suivre de redirection, sans aucune donnée ni identifiant du commerce, corps lu jusqu&#39;à 64 Ko. Un test toutes les 10 secondes par commerce (429 <code>ASSISTANT_TEST_TOO_SOON</code> avec <code>Retry-After</code>). La mention d&#39;une mise en veille n&#39;apparaît que sur un environnement d&#39;essai (<code>POS_ASSISTANT_TRIAL_ENVIRONMENT</code>).</li><li><strong>RG-MCP-52</strong> — L&#39;<strong>activité</strong> montre les 50 dernières lectures en phrases (« a lu les ventes du 10/11 de Le Petit Bistrot »), avec l&#39;assistant ou la clé d&#39;origine, filtrable par assistant (par identifiant, les homonymes sont distingués) ; jamais de nom de route ni d&#39;identifiant technique ; dates dans la langue de l&#39;utilisateur.</li><li><strong>RG-MCP-53</strong> — Les <strong>clés pour intégrateurs</strong> sont repliées par défaut ; la famille Clients (<code>customers:read</code>) est décochée ; le secret n&#39;est affiché qu&#39;une fois, avec la commande <code>claude mcp add</code> complète quand l&#39;adresse du service est connue.</li><li><strong>RG-MCP-54</strong> — <strong>Retirer l&#39;accès</strong> d&#39;un assistant et l&#39;<strong>arrêt d&#39;urgence</strong> (propriétaire seul) demandent une confirmation, sont tracés dans l&#39;audit, et la page se met à jour sans rechargement.</li></ul><h2 id="_4-parcours-ecrans" tabindex="-1">4. Parcours &amp; écrans <a class="header-anchor" href="#_4-parcours-ecrans" aria-label="Permalink to &quot;4. Parcours &amp; écrans&quot;">​</a></h2><p><strong>Back-office web seulement.</strong></p><ol><li>Dans l&#39;assistant, l&#39;utilisateur ajoute l&#39;adresse du serveur MCP Vendora.</li><li>L&#39;assistant ouvre le navigateur sur Vendora ; l&#39;utilisateur se connecte s&#39;il ne l&#39;est pas (retour à la page).</li><li><strong>Connecter un assistant</strong> (<code>/connecter-assistant</code>) : carte de l&#39;assistant (nom, domaine, « Vérifié » / « Non vérifié »), magasins, familles de données, rappel lecture seule, <strong>Autoriser</strong> / <strong>Refuser</strong>. États : demande expirée ou déjà traitée, client ou redirection non reconnus, demande non valide (sans renvoi vers l&#39;assistant), demande ouverte dans un autre navigateur, trop de demandes, rôle insuffisant, accès coupé, formule sans le droit.</li><li>Retour dans l&#39;assistant, qui peut poser sa première question.</li><li><strong>Réglages › Assistant IA</strong> (lot M2, RG-MCP-49 → 54) : adresse du connecteur à copier et QR (bureau), étapes « Connecter Claude » et « Connecter ChatGPT » (bêta), <strong>Tester la connexion</strong>, questions pour bien commencer, <strong>Assistants connectés</strong> et <strong>Retirer l&#39;accès</strong>, activité lisible, clés pour intégrateurs, arrêt d&#39;urgence. La page <strong>Clés d&#39;API</strong> garde les clés classiques et un renvoi vers cette page.</li></ol><p>Captures : <a href="/VendoraSystem-docs/captures/2026-11-11-mcp-m3/README"><code>docs/captures/2026-11-11-mcp-m3/</code></a>, <a href="/VendoraSystem-docs/captures/2026-11-12-mcp-m2/README"><code>docs/captures/2026-11-12-mcp-m2/</code></a>. Fiche de lot : <a href="./../lots/M2">lots/M2.md</a>.</p><h2 id="_5-modele-de-donnees" tabindex="-1">5. Modèle de données <a class="header-anchor" href="#_5-modele-de-donnees" aria-label="Permalink to &quot;5. Modèle de données&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Table</th><th>Rôle</th><th>Isolation</th></tr></thead><tbody><tr><td><code>api_keys</code> (<code>kind</code>, <code>store_ids</code>)</td><td>Clés, dont « Assistant IA »</td><td>RLS par commerce</td></tr><tr><td><code>agent_activity</code> (<code>source</code> : <code>API_KEY</code> / <code>OAUTH</code>)</td><td>Journal des assistants</td><td>RLS par commerce</td></tr><tr><td><code>oauth_clients</code></td><td>Clients connus (<code>CIMD</code> en cache, <code>DCR</code>) et leurs redirections</td><td>Globale, connexion admin seulement</td></tr><tr><td><code>oauth_requests</code></td><td>Demandes d&#39;autorisation (identifiant, code et cookie du navigateur hachés, décision)</td><td>Globale, connexion admin seulement</td></tr><tr><td><code>oauth_grants</code></td><td>Connexions : utilisateur, client, magasins, portées, expiration, retrait (<code>USER</code>, <code>CLIENT</code>, <code>REPLAY</code>)</td><td>RLS par commerce ; <code>pos_app</code> en lecture seule</td></tr><tr><td><code>oauth_tokens</code></td><td>Jetons hachés (<code>ACCESS</code>, <code>REFRESH</code>), rattachés à une connexion</td><td>Connexion admin seulement</td></tr></tbody></table><p>Migrations : <code>V99__agent_access.sql</code> (M0), <code>V103__oauth.sql</code> (M3).</p><h2 id="_6-api" tabindex="-1">6. API <a class="header-anchor" href="#_6-api" aria-label="Permalink to &quot;6. API&quot;">​</a></h2><p>Détail dans <a href="/VendoraSystem-docs/architecture/api-publique">API-PUBLIQUE.md</a> § 1 à § 6.</p><ul><li>Clés et accès : <code>POST /api/v1/api-keys</code> (<code>kind</code>, <code>storeIds</code>), <code>GET /api/v1/api-keys/me</code>, <code>GET</code> / <code>PUT /api/v1/tenant/agent-access</code>, <code>GET /api/v1/agent-activity</code>.</li><li>Agrégations pour les assistants : <code>GET /api/v1/inventory/reorder-suggestions</code>, <code>GET /api/v1/reports/margin-analysis</code>.</li><li>OAuth (hors <code>/api/v1</code>) : <code>GET /.well-known/oauth-authorization-server</code>, <code>POST /oauth/token</code>, <code>POST /oauth/revoke</code>, <code>POST /oauth/register</code>.</li><li>Autorisation (par l&#39;origine du back-office) : <code>GET /api/v1/oauth/authorize</code>.</li><li>Consentement et connexions : <code>GET /api/v1/oauth/requests/{demande}</code>, <code>POST …/approve</code>, <code>POST …/deny</code>, <code>GET /api/v1/oauth/connections</code>, <code>DELETE /api/v1/oauth/connections/{id}</code>.</li><li>Page « Assistant IA » (routes <strong>internes</strong> au back-office, session d&#39;un propriétaire ou d&#39;un administrateur, fermées aux clés et aux jetons d&#39;assistant, absentes de l&#39;OpenAPI publique) : <code>GET /api/v1/assistant/status</code>, <code>POST /api/v1/assistant/test</code>.</li><li>Service <code>mcp/</code> : <code>POST /mcp</code>, <code>GET /healthz</code>, <code>GET /.well-known/oauth-protected-resource</code> (et <code>…/mcp</code>).</li></ul><h2 id="_7-evenements-de-sync" tabindex="-1">7. Événements de sync <a class="header-anchor" href="#_7-evenements-de-sync" aria-label="Permalink to &quot;7. Événements de sync&quot;">​</a></h2><p>Aucun : la fonction est entièrement en ligne et ne touche pas les caisses. Un assistant lit ce que le serveur a reçu ; la fraîcheur annoncée (RG-MCP-14) vient de la dernière synchronisation des caisses.</p><h2 id="_8-permissions-securite" tabindex="-1">8. Permissions &amp; sécurité <a class="header-anchor" href="#_8-permissions-securite" aria-label="Permalink to &quot;8. Permissions &amp; sécurité&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Qui</th></tr></thead><tbody><tr><td>Créer une clé « Assistant IA », autoriser un assistant, retirer un accès</td><td>Propriétaire, administrateur</td></tr><tr><td>Arrêt d&#39;urgence du commerce</td><td>Propriétaire</td></tr><tr><td>Arrêt global</td><td>Équipe Vendora (console, administrateur de la plateforme)</td></tr><tr><td>Appeler <code>/api/v1/oauth/**</code></td><td>Utilisateur du back-office seulement — fermé aux clés et aux jetons</td></tr></tbody></table><p>Aucune action sous PIN manager (rien ne se passe sur une caisse). Points de vigilance tenus par les règles : RG-MCP-08 (secrets), 31 (SSRF, délai ferme), 32 (redirections, pas de redirection ouverte), 33 (PKCE, code), 36 (noms d&#39;assistants), 40 (rejeu), 42 (accès recalculé), 45 à 47 (débit, liaison au navigateur, stockage borné), 48 (interrupteur). <code>pos_app</code> n&#39;a que la <strong>lecture</strong> de <code>oauth_grants</code> ; toute écriture OAuth passe par la connexion admin.</p><p><strong>Limites connues, assumées</strong> : (a) la liaison au navigateur protège le lien de <strong>consentement</strong> ; un lien d&#39;<strong>autorisation</strong> forgé et envoyé à un commerçant ouvre encore une demande dans son navigateur — les parades sont alors l&#39;étiquette « Non vérifié », le domaine de retour affiché, le nom remplacé (RG-MCP-36) et l&#39;accès en lecture seule ; (b) le paramètre <code>resource</code> est vérifié à l&#39;émission du jeton, pas relu à chaque usage (une seule ressource existe aujourd&#39;hui) ; (c) le rejeu d&#39;un jeton de renouvellement est strict, sans fenêtre de grâce.</p><h2 id="_9-cas-limites-erreurs" tabindex="-1">9. Cas limites &amp; erreurs <a class="header-anchor" href="#_9-cas-limites-erreurs" aria-label="Permalink to &quot;9. Cas limites &amp; erreurs&quot;">​</a></h2><ul><li>Demande expirée (10 minutes) ou déjà décidée : 410, l&#39;écran invite à relancer la connexion depuis l&#39;assistant.</li><li>Document client injoignable, trop gros, redirigé, ou qui ne se désigne pas lui-même : écran « assistant non reconnu », aucune redirection. Serveur du document trop lent, ou trop de lectures en cours : écran « trop de demandes », à réessayer.</li><li>Lien de consentement ouvert ailleurs que dans le navigateur qui a lancé la connexion : 403, écran « ouverte dans un autre navigateur ».</li><li>Plafond de demandes en attente ou de clients enregistrés atteint : refus (écran « trop de demandes », ou 503 <code>temporarily_unavailable</code> à l&#39;enregistrement) ; rien n&#39;est stocké.</li><li>Serveur d&#39;autorisation éteint (RG-MCP-48) : 404 partout ; le serveur MCP continue d&#39;accepter les clés.</li><li>L&#39;utilisateur perd un magasin accordé : l&#39;assistant ne le voit plus ; il les perd tous, ou est désactivé : 401.</li><li>Réponse d&#39;un renouvellement perdue par le client : son jeton suivant est un rejeu → connexion révoquée, il faut reconnecter (choix strict, sans fenêtre de grâce).</li><li>Service MCP sans adresse publique configurée : la connexion OAuth n&#39;est pas annoncée, seules les clés servent.</li><li>Hébergement qui dort (plan gratuit) : le réveil dépasse les 10 secondes laissées par les assistants — réveiller le service avant de connecter.</li></ul><h2 id="_10-criteres-d-acceptation" tabindex="-1">10. Critères d&#39;acceptation <a class="header-anchor" href="#_10-criteres-d-acceptation" aria-label="Permalink to &quot;10. Critères d&#39;acceptation&quot;">​</a></h2><ol><li><strong>Étant donné</strong> un serveur MCP appelé sans accès, <strong>quand</strong> un client lit le 401, <strong>alors</strong> il trouve le document de ressource, puis les métadonnées du serveur d&#39;autorisation (S256 seul, client public, document client annoncé).</li><li><strong>Étant donné</strong> une demande dont la redirection n&#39;est pas déclarée, <strong>quand</strong> elle arrive au point d&#39;autorisation, <strong>alors</strong> l&#39;utilisateur voit un écran d&#39;erreur de Vendora et aucune redirection vers cette adresse n&#39;a lieu.</li><li><strong>Étant donné</strong> une demande avec PKCE <code>plain</code> ou sans méthode, <strong>quand</strong> elle arrive, <strong>alors</strong> elle est refusée (<code>invalid_request</code>).</li><li><strong>Étant donné</strong> un propriétaire connecté, <strong>quand</strong> il autorise un magasin et la famille « ventes et rapports », <strong>alors</strong> l&#39;assistant reçoit un jeton qui lit les ventes de ce magasin, pas le stock, pas un autre magasin.</li><li><strong>Étant donné</strong> un code déjà échangé, <strong>quand</strong> il est présenté de nouveau, <strong>alors</strong> il est refusé et les jetons nés de ce code sont révoqués.</li><li><strong>Étant donné</strong> un jeton de renouvellement déjà utilisé, <strong>quand</strong> il est rejoué, <strong>alors</strong> toute la connexion est révoquée.</li><li><strong>Étant donné</strong> une connexion active, <strong>quand</strong> le propriétaire clique « Retirer l&#39;accès », <strong>alors</strong> la requête suivante de l&#39;assistant reçoit 401.</li><li><strong>Étant donné</strong> l&#39;arrêt d&#39;urgence actif ou une formule sans <code>MCP_ACCESS</code>, <strong>quand</strong> l&#39;assistant appelle, <strong>alors</strong> il reçoit les mêmes refus qu&#39;une clé « Assistant IA ».</li><li><strong>Étant donné</strong> un document client dont le nom de domaine pointe vers une adresse privée, <strong>quand</strong> le serveur veut le lire, <strong>alors</strong> il refuse avant toute connexion.</li><li><strong>Étant donné</strong> un jeton d&#39;un commerce, <strong>quand</strong> il sert à lire un autre commerce, <strong>alors</strong> rien n&#39;est visible.</li><li><strong>Étant donné</strong> un client enregistré lui-même, <strong>quand</strong> il envoie une demande incorrecte (par exemple <code>response_type=token</code>), <strong>alors</strong> aucune redirection vers son adresse n&#39;a lieu : écran d&#39;erreur de Vendora.</li><li><strong>Étant donné</strong> une demande ouverte dans un navigateur, <strong>quand</strong> un autre navigateur présente son identifiant, <strong>alors</strong> il ne peut ni la lire, ni l&#39;autoriser, ni la refuser (403).</li><li><strong>Étant donné</strong> un serveur de document client qui ne répond pas (ou très lentement), <strong>quand</strong> le serveur veut le lire, <strong>alors</strong> il abandonne en 5 secondes au plus, et la neuvième lecture simultanée est refusée tout de suite.</li><li><strong>Étant donné</strong> le plafond de demandes en attente ou de clients enregistrés atteint, <strong>quand</strong> une demande de plus arrive, <strong>alors</strong> elle est refusée et rien n&#39;est stocké.</li><li><strong>Étant donné</strong> un même code présenté deux fois en même temps, <strong>quand</strong> les deux échanges se croisent, <strong>alors</strong> un seul reçoit des jetons et la connexion finit révoquée.</li><li><strong>Étant donné</strong> l&#39;interrupteur éteint, <strong>quand</strong> on appelle un point OAuth, <strong>alors</strong> 404 ; allumé sans émetteur ni ressources hors développement, le serveur ne démarre pas.</li><li><strong>Étant donné</strong> un refus de consentement, une révocation par l&#39;assistant ou un rejeu, <strong>quand</strong> on lit le journal d&#39;audit, <strong>alors</strong> chacun y figure avec son motif.</li></ol><h2 id="_11-dependances" tabindex="-1">11. Dépendances <a class="header-anchor" href="#_11-dependances" aria-label="Permalink to &quot;11. Dépendances&quot;">​</a></h2><ul><li>Spec 01 § 6 (clés d&#39;API, portées), spec 17 RG-PLAT-13 / 58 / 59 (formules, droit <code>MCP_ACCESS</code>, arrêt global), spec 13 (page Réglages › Clés d&#39;API), spec 12 (rapports lus par les outils).</li><li>Lots suivants : M2 (page « Assistant IA », hébergement sans mise en veille), M4 (écriture encadrée).</li></ul></div>',1)])])}const m=s(r,[["render",a]]);export{p as __pageData,m as default};
